import React from 'react';
import { Link as RouterLink } from 'react-router-dom'; // Renamed to avoid conflict
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardActionArea from '@mui/material/CardActionArea';
import Typography from '@mui/material/Typography';
import { useTheme } from '@mui/material/styles'; // To access theme properties

const ProcessCard = ({ process }) => {
  const theme = useTheme();

  // Generate a title: use process.title if available, then general_description, then ID
  let displayTitle = 'Untitled Process';
  if (process.title) {
    displayTitle = process.title;
  } else if (process.general_description) {
    const words = process.general_description.split(' ');
    displayTitle = words.slice(0, 7).join(' '); // Show a bit more for title
    if (words.length > 7) displayTitle += '...';
  } else if (process.id) {
    displayTitle = `Process ID: ${process.id.substring(0, 8)}...`;
  }

  const displayDescription = process.general_description || 'No detailed description available.';

  return (
    <Card 
      sx={{
        height: '100%', // Make card fill the grid item
        display: 'flex',
        flexDirection: 'column',
        transition: 'transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out',
        '&:hover': {
          transform: 'translateY(-4px)',
          boxShadow: theme.shadows[4],
        },
      }}
    >
      <CardActionArea
        component={RouterLink}
        to={`/process/${process.id}`}
        sx={{
          display: 'flex',
          flexDirection: 'column',
          flexGrow: 1, // Ensure action area fills the card
          justifyContent: 'space-between', // Pushes date to bottom
          alignItems: 'flex-start', // Align content to the start
          padding: theme.spacing(2), // Use theme spacing
        }}
      >
        <CardContent sx={{ flexGrow: 1, width: '100%', padding: 0 }}> {/* Ensure content takes space, remove default padding */}
          <Typography gutterBottom variant="h6" component="h3" sx={{ fontWeight: 'bold', color: 'primary.main' }}>
            {displayTitle}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ 
            mb: 2, // Margin bottom using theme spacing
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            display: '-webkit-box',
            WebkitLineClamp: 3, // Max 3 lines for description
            WebkitBoxOrient: 'vertical',
          }}>
            {displayDescription}
          </Typography>
        </CardContent>
        <Typography variant="caption" color="text.secondary" sx={{ alignSelf: 'flex-end' }}>
          Created: {process.created_at ? new Date(process.created_at).toLocaleDateString() : 'N/A'}
        </Typography>
      </CardActionArea>
    </Card>
  );
};

export default ProcessCard;
